-- // ADMIN COMMANDSfunction createFaction(thePlayer, commandName, factionType, ...)		if not (...) then			outputChatBox("SYNTAX: /" .. commandName .. " [Faction Type 0=GANG, 1=MAFIA, 2=LAW, 3=GOV, 4=MED, 5=OTHER, 6=NEWS, 7=MECHANIC] [Faction Name]", thePlayer, 255, 194, 14)		else			factionName = table.concat({...}, " ")			factionType = tonumber(factionType)						local theTeam = createTeam(tostring(factionName))			if theTeam then				if mysql:query_free("INSERT INTO factions SET name='" .. mysql:escape_string(factionName) .. "', bankbalance='0', type='" .. mysql:escape_string(factionType) .. "'") then					local id = mysql:insert_id()					exports.pool:allocateElement(theTeam, id)										mysql:query_free("UPDATE factions SET rank_1='Dynamic Rank #1', rank_2='Dynamic Rank #2', rank_3='Dynamic Rank #3', rank_4='Dynamic Rank #4', rank_5='Dynamic Rank #5', rank_6='Dynamic Rank #6', rank_7='Dynamic Rank #7', rank_8='Dynamic Rank #8', rank_9='Dynamic Rank #9', rank_10='Dynamic Rank #10', rank_11='Dynamic Rank #11', rank_12='Dynamic Rank #12', rank_13='Dynamic Rank #13', rank_14='Dynamic Rank #14', rank_15='Dynamic Rank #15', rank_16='Dynamic Rank #16', rank_17='Dynamic Rank #17', rank_18='Dynamic Rank #18', rank_19='Dynamic Rank #19', rank_20='Dynamic Rank #20',  motd='Welcome to the faction.', note = '' WHERE id='" .. id .. "'")					outputChatBox("Faction " .. factionName .. " created with ID #" .. id .. ".", thePlayer, 0, 255, 0)					exports.anticheat:changeProtectedElementDataEx(theTeam, "type", tonumber(factionType))					exports.anticheat:changeProtectedElementDataEx(theTeam, "id", tonumber(id))					exports.anticheat:changeProtectedElementDataEx(theTeam, "money", 0)										local factionRanks = {}					local factionWages = {}					for i = 1, 20 do						factionRanks[i] = "Dynamic Rank #" .. i						factionWages[i] = 100					end					exports.anticheat:changeProtectedElementDataEx(theTeam, "ranks", factionRanks, false)					exports.anticheat:changeProtectedElementDataEx(theTeam, "wages", factionWages, false)					exports.anticheat:changeProtectedElementDataEx(theTeam, "motd", "Welcome to the faction.", false)					exports.anticheat:changeProtectedElementDataEx(theTeam, "note", "", false)					exports.logs:dbLog(thePlayer, 4, theTeam, "MAKE FACTION")					logFactionAction(id, getPlayerName(thePlayer), "created the faction '" .. factionName .. "'") -- [Fix #146]					-- [Fix #114] row is nil on the INSERT path; use the id fetched above					if type(dutyAllow) == "table" then						table.insert(dutyAllow, { id, factionName, { --[[Duty information]] } })					end				else					destroyElement(theTeam)					outputChatBox("Error creating faction.", thePlayer, 255, 0, 0)				end			else				outputChatBox("Faction '" .. tostring(factionName) .. "' already exists.", thePlayer, 255, 0, 0)			end		endendaddCommandHandler("makefaction", createFaction, false, false)function adminRenameFaction(thePlayer, commandName, factionID, ...)		if not (factionID) or not (...)  then			outputChatBox("SYNTAX: /" .. commandName .. " [Faction ID] [Faction Name]", thePlayer, 255, 194, 14)		else			factionID = tonumber(factionID)			if factionID and factionID > 0 then				local theTeam = exports.pool:getElement("team", factionID)				if (theTeam) then					local factionName = table.concat({...}, " ")					mysql:query_free("UPDATE factions SET name='" .. mysql:escape_string(factionName) .. "' WHERE id='" .. factionID .. "'")					local oldName = getTeamName(theTeam)					setTeamName(theTeam, factionName)										exports.global:sendMessageToAdmins(exports.global:getPlayerFullIdentity(thePlayer).." renamed faction '" .. oldName .. "' to '" .. factionName .. "'.")					exports.factions:sendNotiToAllFactionMembers(factionID, "Your faction '"..oldName.."' was renamed to '"..factionName.."' by "..exports.global:getPlayerFullIdentity(thePlayer,1,true))					logFactionAction(factionID, getPlayerName(thePlayer), "renamed the faction to '" .. factionName .. "'") -- [Fix #146]				else					outputChatBox("Invalid Faction ID.", thePlayer, 255, 0, 0)				end			else				outputChatBox("Invalid Faction ID.", thePlayer, 255, 0, 0)			end		endendaddCommandHandler("renamefaction", adminRenameFaction, false, false)function adminSetPlayerFaction(thePlayer, commandName, partialNick, factionID)		factionID = tonumber(factionID)		if not (partialNick) or not (factionID) then			outputChatBox("SYNTAX: /" .. commandName .. " [Player Partial Name/ID] [Faction ID (-1 for none)]", thePlayer, 255, 194, 14)		else			local targetPlayer, targetPlayerNick = exports.global:findPlayerByPartialNick(thePlayer, partialNick)						if targetPlayer then				local theTeam = exports.pool:getElement("team", factionID)				if not theTeam and factionID ~= -1 then					outputChatBox("Invalid Faction ID.", thePlayer, 255, 0, 0)					return				end								local prevFactionID = tonumber(getElementData(targetPlayer, "faction")) or -1 -- [Fix #146]				if mysql:query_free("UPDATE characters SET faction_leader = 0, faction_id = " .. factionID .. ", faction_rank = 1, faction_phone = NULL, duty = 0 WHERE id=" .. getElementData(targetPlayer, "dbid")) then					setPlayerTeam(targetPlayer, theTeam)					if factionID > 0 then						exports.anticheat:changeProtectedElementDataEx(targetPlayer, "faction", factionID, true)						exports.anticheat:changeProtectedElementDataEx(targetPlayer, "factionrank", 1, true)						exports.anticheat:changeProtectedElementDataEx(targetPlayer, "factionphone", nil, true)						--triggerClientEvent(targetPlayer, "updateFactionInfo", targetPlayer, factionID, 1)						exports.anticheat:changeProtectedElementDataEx(targetPlayer, "factionleader", 0, true)						triggerEvent("duty:offduty", targetPlayer)												outputChatBox("Player " .. targetPlayerNick .. " is now a member of faction '" .. getTeamName(theTeam) .. "' (#" .. factionID .. ").", thePlayer, 0, 255, 0)												triggerEvent("onPlayerJoinFaction", targetPlayer, theTeam)						outputChatBox("You were set to Faction '" .. getTeamName(theTeam) .. "'.", targetPlayer, 255, 194, 14)												exports.logs:dbLog(thePlayer, 4, { targetPlayer, theTeam }, "SET TO FACTION")						logFactionAction(factionID, getPlayerName(thePlayer), "added " .. targetPlayerNick .. " to the faction") -- [Fix #146]					else						-- Citizen bug fix by Anthony						local citizenTeam = getTeamFromName("Citizen")						setPlayerTeam(targetPlayer, citizenTeam)						exports.anticheat:changeProtectedElementDataEx(targetPlayer, "faction", -1, true)						exports.anticheat:changeProtectedElementDataEx(targetPlayer, "factionrank", 1, true)						exports.anticheat:changeProtectedElementDataEx(targetPlayer, "factionphone", nil, true)						exports.anticheat:changeProtectedElementDataEx(targetPlayer, "factionleader", 0, true)						--triggerClientEvent(targetPlayer, "updateFactionInfo", targetPlayer, -1, 1)						if getElementData(targetPlayer, "duty") and getElementData(targetPlayer, "duty") > 0 then							takeAllWeapons(targetPlayer)							exports.anticheat:changeProtectedElementDataEx(targetPlayer, "duty", 0, true)						end												outputChatBox("Player " .. targetPlayerNick .. " was set to no faction.", thePlayer, 0, 255, 0)						outputChatBox("You were removed from your faction.", targetPlayer, 255, 0, 0)												exports.logs:dbLog(thePlayer, 4, { targetPlayer }, "REMOVE FROM FACTION")						if prevFactionID and prevFactionID > 0 then logFactionAction(prevFactionID, getPlayerName(thePlayer), "removed " .. targetPlayerNick .. " from the faction") end -- [Fix #146]					end				end			end		endendaddCommandHandler("setfaction", adminSetPlayerFaction, false, false)function adminSetFactionLeader(thePlayer, commandName, partialNick, factionID)		factionID = tonumber(factionID)		if not (partialNick) or not (factionID)  then			outputChatBox("SYNTAX: /" .. commandName .. " [Player Partial Name] [Faction ID]", thePlayer, 255, 194, 14)		elseif factionID > 0 then			local targetPlayer, targetPlayerNick = exports.global:findPlayerByPartialNick(thePlayer, partialNick)						if targetPlayer then				local theTeam = exports.pool:getElement("team", factionID)				if not theTeam then					outputChatBox("Invalid Faction ID.", thePlayer, 255, 0, 0)					return				end								if mysql:query_free("UPDATE characters SET faction_leader = 1, faction_id = " .. tonumber(factionID) .. ", faction_rank = 1, faction_phone = NULL, duty = 0 WHERE id = " .. getElementData(targetPlayer, "dbid")) then					setPlayerTeam(targetPlayer, theTeam)					exports.anticheat:changeProtectedElementDataEx(targetPlayer, "faction", factionID, true)					exports.anticheat:changeProtectedElementDataEx(targetPlayer, "factionrank", 1, true)					exports.anticheat:changeProtectedElementDataEx(targetPlayer, "factionleader", 1, true)					exports.anticheat:changeProtectedElementDataEx(targetPlayer, "factionphone", nil, true)					--triggerClientEvent(targetPlayer, "updateFactionInfo", targetPlayer, factionID, 1)					triggerEvent("duty:offduty", targetPlayer)										outputChatBox("Player " .. targetPlayerNick .. " is now a leader of faction '" .. getTeamName(theTeam) .. "' (#" .. factionID .. ").", thePlayer, 0, 255, 0)											triggerEvent("onPlayerJoinFaction", targetPlayer, theTeam)					outputChatBox("You were set to the leader of Faction '" .. getTeamName(theTeam) .. "'.", targetPlayer, 255, 194, 14)										exports.logs:dbLog(thePlayer, 4, { targetPlayer, theTeam }, "SET TO FACTION LEADER")					logFactionAction(factionID, getPlayerName(thePlayer), "set " .. targetPlayerNick .. " as faction leader") -- [Fix #146]					exports.factions:sendNotiToAllFactionMembers(factionID, targetPlayerNick .. " is now a leader of your faction '" .. getTeamName(theTeam) .. "'!", "Set by "..exports.global:getPlayerFullIdentity(thePlayer))				else					outputChatBox("Invalid Faction ID.", thePlayer, 255, 0, 0)				end			end		endendaddCommandHandler("setfactionleader", adminSetFactionLeader, false, false)function adminSetFactionRank(thePlayer, commandName, partialNick, factionRank)		factionRank = math.ceil(tonumber(factionRank) or -1)		if not (partialNick) or not (factionRank)  then			outputChatBox("SYNTAX: /" .. commandName .. " [Player Partial Name] [Faction Rank, 1-20]", thePlayer, 255, 194, 14)		elseif factionRank >= 1 and factionRank <= 20 then			local targetPlayer, targetPlayerNick = exports.global:findPlayerByPartialNick(thePlayer, partialNick)						if targetPlayer then				local theTeam = getPlayerTeam(targetPlayer)				if not theTeam or getTeamName( theTeam ) == "Citizen" then					outputChatBox("Player is not in a faction.", thePlayer, 255, 0, 0)					return				end								if mysql:query_free("UPDATE characters SET faction_rank = " .. factionRank .. " WHERE id = " .. getElementData(targetPlayer, "dbid")) then					exports.anticheat:changeProtectedElementDataEx(targetPlayer, "factionrank", factionRank, true)										outputChatBox("Player " .. targetPlayerNick .. " is now rank " .. factionRank .. ".", thePlayer, 0, 255, 0)					outputChatBox("Admin " .. getPlayerName(thePlayer):gsub("_"," ") .. " set you to rank " .. factionRank .. ".", targetPlayer, 0, 255, 0)										exports.logs:dbLog(thePlayer, 4, { targetPlayer, theTeam }, "SET TO FACTION RANK " .. factionRank)					logFactionAction(getElementData(theTeam, "id"), getPlayerName(thePlayer), "set " .. targetPlayerNick .. " to rank " .. factionRank) -- [Fix #146]				else					outputChatBox("Error #125151 - Report on Mantis.", thePlayer, 255, 0, 0)				end			end		else			outputChatBox( "Invalid Rank - valid ones are 1 to 20", thePlayer, 255, 0, 0 )		endendaddCommandHandler("setfactionrank", adminSetFactionRank, false, false)function adminDeleteFaction(thePlayer, commandName, factionID)		if not (factionID)  then			outputChatBox("SYNTAX: /" .. commandName .. " [Faction ID]", thePlayer, 255, 194, 14)		else			factionID = tonumber(factionID)			if factionID and factionID > 0 then				local theTeam = exports.pool:getElement("team", factionID)								if (theTeam) then										mysql:query_free("DELETE FROM factions WHERE id='" .. factionID .. "'")										outputChatBox("Faction #" .. factionID .. " was deleted.", thePlayer, 0, 255, 0)					exports.logs:dbLog(thePlayer, 4, theTeam, "DELETE FACTION")					logFactionAction(factionID, getPlayerName(thePlayer), "deleted the faction") -- [Fix #146]					exports.factions:sendNotiToAllFactionMembers(factionID, "Your faction '"..getTeamName( theTeam ).."' was deleted by "..exports.global:getPlayerFullIdentity(thePlayer, 1, true).."!")					local civTeam = getTeamFromName("Citizen")					for key, value in pairs( getPlayersInTeam( theTeam ) ) do						setPlayerTeam( value, civTeam )						exports.anticheat:changeProtectedElementDataEx( value, "faction", -1, true )						--triggerClientEvent(targetPlayer, "updateFactionInfo", targetPlayer, -1, 1)					end					destroyElement( theTeam )								else					outputChatBox("Invalid Faction ID.", thePlayer, 255, 0, 0)				end			else				outputChatBox("Invalid Faction ID.", thePlayer, 255, 0, 0)			end		endendaddCommandHandler("delfaction", adminDeleteFaction, false, false)function adminShowFactions(thePlayer)		local result = mysql:query("SELECT id, name, type, (SELECT COUNT(*) FROM characters c WHERE c.faction_id = f.id) AS members FROM factions f ORDER BY id ASC")		if result then			local factions = { }						while true do				local row = mysql:fetch_assoc(result)				if not row then break end								table.insert( factions, { row.id, row.name, row.type, ( getTeamFromName( row.name ) and #getPlayersInTeam( getTeamFromName( row.name ) ) or "?" ) .. " / " .. row.members } )			end						mysql:free_result(result)			triggerClientEvent(thePlayer, "showFactionList", getRootElement(), factions)		else			outputChatBox("Error 300001 - Report on forums.", thePlayer, 255, 0, 0)		endendaddCommandHandler("showfactions", adminShowFactions, false, false)function adminShowFactionOnlinePlayers(thePlayer, commandName, factionID)		if not (factionID)  then			outputChatBox("SYNTAX: /" .. commandName .. " [Faction ID]", thePlayer, 255, 194, 14)		else			factionID = tonumber(factionID)			if factionID and factionID > 0 then				local theTeam = exports.pool:getElement("team", factionID)				local theTeamName = getTeamName(theTeam)				local teamPlayers = getPlayersInTeam(theTeam)								if #teamPlayers == 0 then					outputChatBox("There are no players online in faction '".. theTeamName .."'", thePlayer, 255, 194, 14)				else					local teamRanks = getElementData(theTeam, "ranks")					outputChatBox("Players online in faction '".. theTeamName .."':", thePlayer, 255, 194, 14)					for k, teamPlayer in ipairs(teamPlayers) do						local leader = ""						local playerRank = teamRanks [ getElementData(teamPlayer, "factionrank") ]						if (getElementData(teamPlayer, "factionleader") == 1) then							leader = "LEADER "						end						outputChatBox("  "..leader.." ".. getPlayerName(teamPlayer) .." - "..playerRank, thePlayer, 255, 194, 14)					end				end			else				outputChatBox("Faction not found.", thePlayer, 255, 194, 14)			end		endendaddCommandHandler("showfactionplayers", adminShowFactionOnlinePlayers, false, false)function callbackAdminPlayersFaction(teamID)	-- [Fix #113] explicit gate in the handler itself (same helper style as adminShowFactionOnlinePlayers)	if (exports.integration:isPlayerTrialAdmin(client) or exports.integration:isPlayerSupporter(client)) then		adminShowFactionOnlinePlayers(client, "showfactionplayers", teamID)	endend
addEvent("faction:admin:showplayers", true )addEventHandler("faction:admin:showplayers", getRootElement(), callbackAdminPlayersFaction)addEvent('faction:admin:showf3', true)addEventHandler('faction:admin:showf3', root,	function(id)		if exports.integration:isPlayerTrialAdmin(client) --[[or exports.integration:isPlayerSupporter(client)]] then			-- [Fix #108] leader flag is computed server-side; the client-supplied one is ignored			showFactionMenuEx(client, id, hasPlayerAccessOverFaction(client, tonumber(id)))		end	end)
function setFactionMoney(thePlayer, commandName, factionID, amount)		if not (factionID) or not (amount)  then			outputChatBox("SYNTAX: /" .. commandName .. " [Faction ID] [Money]", thePlayer, 255, 194, 14)		else			factionID = tonumber(factionID)			if factionID and factionID > 0 then				local theTeam = exports.pool:getElement("team", factionID)				amount = tonumber(amount) or 0				if amount and amount > 500000*2 then					outputChatBox("For security reason, you're not allowed to set more than $1,000,000 at once to a faction.", thePlayer, 255, 0, 0)					return false				end								if (theTeam) then					if exports.global:setMoney(theTeam, amount) then						outputChatBox("Set faction '" .. getTeamName(theTeam) .. "'s money to " .. amount .. " $.", thePlayer, 255, 194, 14)						exports.factions:sendNotiToAllFactionMembers(factionID, exports.global:getPlayerFullIdentity(thePlayer, 1).." has set your faction bank to $"..exports.global:formatMoney(amount)..".", nil, true)						logFactionAction(factionID, getPlayerName(thePlayer), "set the faction money to $" .. exports.global:formatMoney(amount)) -- [Fix #146]					else						outputChatBox("Could not set money to that faction.", thePlayer, 255, 194, 14)					end				else					outputChatBox("Invalid faction ID.", thePlayer, 255, 194, 14)				end			else				outputChatBox("Invalid faction ID.", thePlayer, 255, 194, 14)			end		endendaddCommandHandler("setfactionmoney", setFactionMoney, false, false)-- [Fix #148] live-data setters. Gating is TWO-layered: staff_manager already-- maps both command names (command_gates_s.lua COMMAND_RIGHTS:-- "setfactionhotline" / "setfactioncolor") so the global onPlayerCommand gate-- cancels the typed command for any rank that lacks the right, and the-- explicit isPlayerTrialAdmin check below mirrors the neighbouring-- /setfaction and /respawnfaction handlers for the legacy (no Vortex rank)-- ladder.function adminSetFactionHotline(thePlayer, commandName, factionID, number)		factionID = tonumber(factionID)		if not factionID or factionID <= 0 or number == nil then			outputChatBox("SYNTAX: /" .. commandName .. " [Faction ID] [Number, or - to clear]", thePlayer, 255, 194, 14)			return		end		local theTeam = exports.pool:getElement("team", factionID)		if not theTeam then			outputChatBox("Invalid Faction ID.", thePlayer, 255, 0, 0)			return		end		local value = tostring(number)		if value == "-" or value == "" then			value = ""		end		if value ~= "" and (not value:match("^[%d%+%-%s%(%)%.]+$") or #value > 32) then			outputChatBox("Invalid hotline number - up to 32 characters, digits and + - ( ) . only.", thePlayer, 255, 0, 0)			return		end		if mysql:query_free("UPDATE factions SET hotline='" .. mysql:escape_string(value) .. "' WHERE id='" .. factionID .. "'") then			exports.anticheat:changeProtectedElementDataEx(theTeam, "hotline", value, true)			if value == "" then				outputChatBox("Cleared the hotline of faction '" .. getTeamName(theTeam) .. "'.", thePlayer, 0, 255, 0)				logFactionAction(factionID, getPlayerName(thePlayer), "cleared the faction hotline") -- [Fix #146]			else				outputChatBox("Set the hotline of faction '" .. getTeamName(theTeam) .. "' to " .. value .. ".", thePlayer, 0, 255, 0)				logFactionAction(factionID, getPlayerName(thePlayer), "set the faction hotline to " .. value) -- [Fix #146]			end		else			outputChatBox("Error setting the faction hotline, Contact an admin.", thePlayer, 255, 0, 0)		endendaddCommandHandler("setfactionhotline", adminSetFactionHotline, false, false)function adminSetFactionColor(thePlayer, commandName, factionID, hexColor)		factionID = tonumber(factionID)		if not factionID or factionID <= 0 or not hexColor then			outputChatBox("SYNTAX: /" .. commandName .. " [Faction ID] [Color, #RRGGBB or RRGGBB]", thePlayer, 255, 194, 14)			return		end		local theTeam = exports.pool:getElement("team", factionID)		if not theTeam then			outputChatBox("Invalid Faction ID.", thePlayer, 255, 0, 0)			return		end		local color = tostring(hexColor):gsub("^#", "")		if not color:match("^%x%x%x%x%x%x$") then			outputChatBox("Invalid color - use #RRGGBB or RRGGBB (hex).", thePlayer, 255, 0, 0)			return		end		color = "#" .. string.upper(color)		if mysql:query_free("UPDATE factions SET color='" .. mysql:escape_string(color) .. "' WHERE id='" .. factionID .. "'") then			exports.anticheat:changeProtectedElementDataEx(theTeam, "color", color, true)			outputChatBox("Set the color of faction '" .. getTeamName(theTeam) .. "' to " .. color .. ".", thePlayer, 0, 255, 0)			logFactionAction(factionID, getPlayerName(thePlayer), "set the faction color to " .. color) -- [Fix #146]		else			outputChatBox("Error setting the faction color, Contact an admin.", thePlayer, 255, 0, 0)		endendaddCommandHandler("setfactioncolor", adminSetFactionColor, false, false)-----function loadWelfare( )	local result = exports.mysql:query_fetch_assoc( "SELECT value FROM settings WHERE name = 'welfare'" )	if result then		if not result.value then			mysql:query_free( "INSERT INTO settings (name, value) VALUES ('welfare', " .. unemployedPay .. ")" )		else			unemployedPay = tonumber( result.value ) or 150		end	endendaddEventHandler( "onResourceStart", resourceRoot, loadWelfare )function getTax(thePlayer)	loadWelfare( )	outputChatBox( "Welfare: $" .. exports.global:formatMoney(unemployedPay), thePlayer, 255, 194, 14 )	outputChatBox( "Tax: " .. ( exports.global:getTaxAmount(thePlayer) * 100 ) .. "%", thePlayer, 255, 194, 14 )	outputChatBox( "Income Tax: " .. ( exports.global:getIncomeTaxAmount(thePlayer) * 100 ) .. "%", thePlayer, 255, 194, 14 )endaddCommandHandler("gettax", getTax, false, false)function setFactionBudget(thePlayer, commandName, factionID, amount)	if getPlayerTeam(thePlayer) == getTeamFromName("Government of Los Santos") and getElementData(thePlayer, "factionrank") >= 15 then		local amount = tonumber( amount )		if not factionID or not amount or amount < 0 then			outputChatBox("SYNTAX: /" .. commandName .. " [Faction ID] [Money]", thePlayer, 255, 194, 14)		else			factionID = tonumber(factionID)			if factionID and factionID > 0 then				local theTeam = exports.pool:getElement("team", factionID)				amount = tonumber(amount)								if (theTeam) then					if getElementData(theTeam, "type") >= 2 and getElementData(theTeam, "type") <= 6 then						if exports.global:takeMoney(getPlayerTeam(thePlayer), amount) then							exports.global:giveMoney(theTeam, amount)							outputChatBox("You added $" .. exports.global:formatMoney(amount) .. " to the budget of '" .. getTeamName(theTeam) .. "' (Total: " .. exports.global:getMoney(theTeam) .. ").", thePlayer, 255, 194, 14)							mysql:query_free( "INSERT INTO wiretransfers (`from`, `to`, `amount`, `reason`, `type`) VALUES (" .. -getElementData(getPlayerTeam(thePlayer), "id") .. ", " .. -getElementData(theTeam, "id") .. ", " .. amount .. ", '', 8)" )							logFactionAction(factionID, getPlayerName(thePlayer), "added $" .. exports.global:formatMoney(amount) .. " to the faction budget") -- [Fix #146]						else							outputChatBox("You can't afford this.", thePlayer, 255, 194, 14)						end					else						outputChatBox("You can't set a budget for that faction.", thePlayer, 255, 194, 14)					end				else					outputChatBox("Invalid faction ID.", thePlayer, 255, 194, 14)				end			else				outputChatBox("Invalid faction ID.", thePlayer, 255, 194, 14)			end		end	endendaddCommandHandler("setbudget", setFactionBudget, false, false)function setTax(thePlayer, commandName, amount)	if getPlayerTeam(thePlayer) == getTeamFromName("Government of Los Santos") and getElementData(thePlayer, "factionrank") >= 15 then		local amount = tonumber( amount )		if not amount or amount < 0 or amount > 30 then			outputChatBox("SYNTAX: /" .. commandName .. " [0-30%]", thePlayer, 255, 194, 14)		else			exports.global:setTaxAmount(amount)			outputChatBox("New Tax is " .. amount .. "%", thePlayer, 0, 255, 0)		end	endendaddCommandHandler("settax", setTax, false, false)function setIncomeTax(thePlayer, commandName, amount)	if getPlayerTeam(thePlayer) == getTeamFromName("Government of Los Santos") and getElementData(thePlayer, "factionrank") >= 15 then		local amount = tonumber( amount )		if not amount or amount < 0 or amount > 25 then			outputChatBox("SYNTAX: /" .. commandName .. " [0-25%]", thePlayer, 255, 194, 14)		else			exports.global:setIncomeTaxAmount(amount)			outputChatBox("New Income Tax is " .. amount .. "%", thePlayer, 0, 255, 0)		end	endendaddCommandHandler("setincometax", setIncomeTax, false, false)function setWelfare(thePlayer, commandName, amount)	if getPlayerTeam(thePlayer) == getTeamFromName("Government of Los Santos") and getElementData(thePlayer, "factionrank") >= 15 then		local amount = tonumber( amount )		if not amount or amount <= 0 then			outputChatBox("SYNTAX: /" .. commandName .. " [Money]", thePlayer, 255, 194, 14)		elseif mysql:query_free( "UPDATE settings SET value = " .. unemployedPay .. " WHERE name = 'welfare'" ) then			unemployedPay = amount			outputChatBox("New Welfare is $" .. exports.global:formatMoney(unemployedPay) .. "/payday", thePlayer, 0, 255, 0)		else			outputChatBox("Error 129314 - Report on Mantis.", thePlayer, 255, 0, 0)		end	endendaddCommandHandler("setwelfare", setWelfare, false, false)function issueGovLicense(thePlayer, commandName, type, ...)	local licenseTypes = {"Business License - Regular", "Business License - Premium", "Adult Entertainment License", "Gambling License", "Liquor License"}	if getPlayerTeam(thePlayer) == getTeamFromName("Government of Los Santos") and getElementData(thePlayer, "factionrank") >= 3 then		local type = tonumber(type)		if not type or not licenseTypes[type] or not ... then			outputChatBox("SYNTAX: /" .. commandName .. " [type] [biz name]", thePlayer, 255, 194, 14)			for k, v in ipairs(licenseTypes) do			outputChatBox("  " .. k .. ": " .. v, thePlayer, 255, 194, 14)			end		else			local text = licenseTypes[type] .. " - " .. table.concat({...}, " ")			local success, error = exports.global:giveItem(thePlayer, 80, text)			if success then				outputChatBox("Created a " .. text .. ".", thePlayer, 0, 255, 0)			else				outputChatBox(error, thePlayer, 255, 0, 0)			end		end	endendaddCommandHandler("govlicense", issueGovLicense, false, false)--function respawnFactionVehicles(thePlayer, commandName, factionID)		local factionID = tonumber(factionID)		if (factionID) and (factionID > 0) then			local theTeam = exports.pool:getElement("team", factionID)			if (theTeam) then				for key, value in ipairs(exports.pool:getPoolElementsByType("vehicle")) do					local faction = tonumber(getElementData(value, "faction"))					if (faction == factionID and not getVehicleOccupant(value, 0) and not getVehicleOccupant(value, 1) and not getVehicleOccupant(value, 2) and not getVehicleOccupant(value, 3) and not getVehicleTowingVehicle(value)) then						respawnVehicle(value)						setElementInterior(value, getElementData(value, "interior"))						setElementDimension(value, getElementData(value, "dimension"))					end				end								local hiddenAdmin = tonumber(getElementData(thePlayer, "hiddenadmin"))				local adminTitle = exports.global:getPlayerAdminTitle(thePlayer)				local username = getPlayerName(thePlayer):gsub("_"," ")								for k,v in ipairs(getPlayersInTeam(theTeam)) do					outputChatBox((hiddenAdmin == 0 and adminTitle .. " " .. username or "Hidden Admin") .. " respawned all unoccupied faction vehicles.", v)				end								exports.global:sendMessageToAdmins("AdmCmd: " .. tostring(adminTitle) .. " " .. username .. " respawned all unoccupied faction vehicles for faction ID " .. factionID .. ".")				exports.logs:dbLog(thePlayer, 4, theTeam, "FACTION RESPAWN for " .. factionID)			else				outputChatBox("Invalid faction ID.", thePlayer, 255, 0, 0, false)			end		else			outputChatBox("SYNTAX: /" .. commandName .. " [Faction ID]", thePlayer, 255, 194, 14, false)		endendaddCommandHandler("respawnfaction", respawnFactionVehicles, false, false)-- // Chaos - Script stealers go away, make something for yourself.-- [Fix #117] duty_allowed id counter for this file (the shared global maxIndex is also used by s_faction_system.lua)local dutyMaxIndex = 0function adminDutyStart()
	local result = mysql:query("SELECT id, name FROM factions WHERE type >= 2 ORDER BY id ASC")	local max = mysql:query("SELECT id FROM duty_allowed ORDER BY id DESC LIMIT 0, 1")	if result and max then		dutyAllow = { }		dutyAllowChanges = { }		i = 0		local maxrow = mysql:fetch_assoc(max) or { }		maxIndex = tonumber(maxrow.id) or 0		dutyMaxIndex = maxIndex -- [Fix #117] remember the duty_allowed id high-water mark					while true do			local row = mysql:fetch_assoc(result)			if not row then break end			table.insert(dutyAllow, { row.id, row.name, { --[[Duty information]] } })			i = i+1							local result1 = mysql:query("SELECT * FROM duty_allowed WHERE faction="..tonumber(row.id))			if result1 then				while true do					local row1 = mysql:fetch_assoc(result1)					if not row1 then break end					table.insert(dutyAllow[i][3], { row1.id, tonumber(row1.itemID), row1.itemValue })				end				mysql:free_result(result1) -- [Fix #124] free while result1 is still in scope			end
		end		setElementData(resourceRoot, "maxIndex", maxIndex)		setElementData(resourceRoot, "dutyAllowTable", dutyAllow)		mysql:free_result(result)		mysql:free_result(max)
	else		outputDebugString("[Factions] ERROR: Duty allow permissions failed.")	endendaddEventHandler("onResourceStart", resourceRoot, adminDutyStart)function getAllowList(factionID)	local factionID = tonumber(factionID)	if factionID and type(dutyAllow) == "table" then		local key -- [Fix #125] per-call local; the old global kept the previous faction's value		for k,v in pairs(dutyAllow) do			if type(v) == "table" and tonumber(v[1]) == factionID then				key = k				break			end		end		if key and type(dutyAllow[key]) == "table" and type(dutyAllow[key][3]) == "table" then -- [Fix #125] nil-guard			return dutyAllow[key][3]		end		return nil -- [Fix #125] faction has no cached entry	endend
-- [Fix #107] tracks who holds the /dutyadmin lock so it can be released on quitlocal dutyAdminHolder = nilfunction adminDuty(thePlayer)		if not getElementData(resourceRoot, "dutyadmin") and type(dutyAllow) == "table" then			triggerClientEvent(thePlayer, "adminDutyAllow", resourceRoot, dutyAllow, dutyAllowChanges)			setElementData( resourceRoot, "dutyadmin", true )			dutyAdminHolder = thePlayer -- [Fix #107]		elseif type(dutyAllow) ~= "table" then			outputChatBox("There was a issue with the startup caching of this resource. Contact a Scripter.", thePlayer, 255, 0, 0)		elseif exports.integration:isPlayerLeadAdmin(thePlayer) then			-- [Fix #107] lead admins may take over a stuck/held lock			if isElement(dutyAdminHolder) and dutyAdminHolder ~= thePlayer then				outputChatBox(getPlayerName(thePlayer) .. " has taken over the duty permission editor.", dutyAdminHolder, 255, 194, 14)			end			removeElementData(resourceRoot, "dutyadmin")			dutyAdminHolder = nil			triggerClientEvent(thePlayer, "adminDutyAllow", resourceRoot, dutyAllow, dutyAllowChanges)			setElementData( resourceRoot, "dutyadmin", true )			dutyAdminHolder = thePlayer			outputChatBox("You have taken over the duty permission editor.", thePlayer, 255, 194, 14)		else			outputChatBox("Oops! Someone is already editing duty permissions. Sorry!", thePlayer, 255, 0, 0) -- No time to set up proper syncing + kinda not needed.		endendaddCommandHandler("dutyadmin", adminDuty, false, false)-- [Fix #107] release the lock when its holder disconnectsaddEventHandler("onPlayerQuit", getRootElement(), function()	if dutyAdminHolder == source then		dutyAdminHolder = nil		if getElementData(resourceRoot, "dutyadmin") then			removeElementData(resourceRoot, "dutyadmin")		end	endend)
function saveChanges()	outputDebugString("[Factions] Saving duty allow changes...")	local tick = getTickCount()	if type(dutyAllowChanges) ~= "table" then		return	end	for key,value in pairs(dutyAllowChanges) do		local op = tonumber(value[2])		if op == 0 then -- Delete row			-- [Fix #115] value[3] must be a real duty_allowed id			local deleteID = tonumber(value[3])			if deleteID then				mysql:query_free("DELETE FROM duty_allowed WHERE id="..mysql:escape_string(deleteID))			end		elseif op == 1 then			-- [Fix #117] id comes from the server-side allocator (value[6]); otherwise AUTO_INCREMENT			local newID = tonumber(value[6])			local insertQuery = "INSERT INTO duty_allowed SET "			if newID then				insertQuery = insertQuery .. "id=" .. mysql:escape_string(newID) .. ", "			end			insertQuery = insertQuery .. "faction=" .. mysql:escape_string(tonumber(value[1])) .. ", itemID=" .. mysql:escape_string(tonumber(value[3])) .. ", itemValue='" .. mysql:escape_string(value[4]) .. "'"			mysql:query_free(insertQuery)		end	end	outputDebugString("[Factions] Completed in ".. math.floor((getTickCount()-tick)/60) .." seconds.")end
addEventHandler("onResourceStop", resourceRoot, saveChanges)-- [Fix #105] validates the dutyAllow payload (depth 1-3) before it replaces the cached tablelocal function isValidAllowTable(tbl)	if type(tbl) ~= "table" then		return false	end	for _, entry in pairs(tbl) do		if type(entry) ~= "table" then			return false		end		if not tonumber(entry[1]) then -- faction id			return false		end		if type(entry[2]) ~= "string" and type(entry[2]) ~= "number" then -- faction name			return false		end		if entry[3] ~= nil and type(entry[3]) ~= "table" then -- allow list			return false		end		if type(entry[3]) == "table" then			for _, row in pairs(entry[3]) do				if type(row) ~= "table" then					return false				end				for _, cell in pairs(row) do					if type(cell) == "table" or type(cell) == "boolean" then						return false					end				end			end		end	end	return trueend-- [Fix #105] validates the dutyAllowChanges payload before it replaces the pending changeslocal function isValidChangesTable(tbl)	if type(tbl) ~= "table" then		return false	end	for _, change in pairs(tbl) do		if type(change) ~= "table" then			return false		end		local factionID = tonumber(change[1])		local op = tonumber(change[2])		if not factionID or not op then			return false		end		if op == 0 then			if not tonumber(change[3]) then -- [Fix #115] duty_allowed id to delete				return false			end		elseif op == 1 then			if not tonumber(change[3]) then -- item id				return false			end			local valueType = type(change[4])			if valueType ~= "string" and valueType ~= "number" then -- item value				return false			end			if change[5] ~= nil and type(change[5]) ~= "number" and type(change[5]) ~= "string" then -- [Fix #117] client row handle				return false			end		else			return false		end	end	return trueendfunction updateTable(newTable, changesTable)	-- [Fix #105] only senior admins / scripters may replace the server-side duty tables	if not (exports.integration:isPlayerSeniorAdmin(client) or exports.integration:isPlayerScripter(client)) then		outputDebugString("[Factions] dutyAdmin:Save rejected: no access for " .. tostring(client and getPlayerName(client) or "unknown"), 2)		return	end	if not isValidAllowTable(newTable) or not isValidChangesTable(changesTable) then		outputDebugString("[Factions] dutyAdmin:Save rejected: malformed payload from " .. tostring(client and getPlayerName(client) or "unknown"), 2)		return	end	-- [Fix #117] allocate duty_allowed ids server-side for rows added this session	if tonumber(dutyMaxIndex) then		for _, change in pairs(changesTable) do			if tonumber(change[2]) == 1 and not change[6] then				dutyMaxIndex = dutyMaxIndex + 1				change[6] = dutyMaxIndex				local tempID = tonumber(change[5])				local factionID = tonumber(change[1])				if tempID and factionID and type(newTable[factionID]) == "table" and type(newTable[factionID][3]) == "table" then					for _, row in pairs(newTable[factionID][3]) do						if tonumber(row[1]) == tempID then							row[1] = dutyMaxIndex -- keep the cached table in sync with the assigned id							break						end					end				end			end		end	end	dutyAllow = newTable	dutyAllowChanges = changesTable	dutyAdminHolder = nil -- [Fix #107] editor closed, the lock is free again	removeElementData(resourceRoot, "dutyadmin")	setElementData(resourceRoot, "dutyAllowTable", dutyAllow)end
addEvent("dutyAdmin:Save", true)addEventHandler("dutyAdmin:Save", resourceRoot, updateTable)-- [Fix #102] removed the sacksupporter backdoor (unconditional Admin=4 UPDATE accounts)
